vars.processors:
- add_fields:
    target: event
    fields:
      category: network
      module: suricata
- script:
    lang: javascript
    source: |
      function process(event) {
        var et = event.Get("event_type") || "other";
        event.Put("@metadata.pipeline", et === "alert" ? "suricata.alert" : "suricata.common");
        var src = (event.Get("log.file.fingerprint") || "") + "|" + (event.Get("log.offset") || "");
        var h = 5381;
        for (var i = 0; i < src.length; i++) { h = ((h << 5) + h + src.charCodeAt(i)) >>> 0; }
        event.Put("metadata._id", "nss-" + h.toString(16));
      }
